package com.lmspilot.filestorage.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="stored_files") public class StoredFileEntity { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false) public UUID ownerId; @Column(nullable=false,length=260) public String originalName=""; @Column(nullable=false,length=260,unique=true) public String storageKey=""; @Column(nullable=false,length=160) public String contentType="application/octet-stream"; @Column(nullable=false) public long sizeBytes; @Column(nullable=false,length=64) public String sha256=""; @Column(nullable=false,length=80) public String purpose="GENERAL"; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) public StoredFileStatus status=StoredFileStatus.AVAILABLE; @Column(nullable=false) public Instant createdAt=Instant.now(); public Instant deletedAt; public StoredFileEntity(){} }
